// rle: run-length encoding of 8 MiB of generated bytes with runs of 1 to
// 16, as (length, byte) pairs with lengths up to 255, then decoded and
// compared. Prints the encoded size, the sum of the encoded bytes and 1
// when the decoded bytes equal the original.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int64_t mix(int64_t b) { return b * 2654435761LL >> 13; }

int main(void) {
    const int64_t n = 1 << 23;
    uint8_t *data = malloc(n), *enc = malloc(2 * n), *dec = malloc(n);
    for (int64_t i = 0; i < n; i++) {
        int64_t b = i / 16, v = 8 * (b & 1) + (mix(b) & 3);
        data[i] = (uint8_t)(i % 16 < mix(b + 7) % 16 + 1 ? v : v + 4);
    }
    int64_t m = 0;
    for (int64_t i = 0; i < n;) {
        int64_t j = i;
        while (j < n && data[j] == data[i] && j - i < 255) j++;
        enc[m++] = (uint8_t)(j - i);
        enc[m++] = data[i];
        i = j;
    }
    int64_t d = 0, sum = 0;
    for (int64_t k = 0; k < m; k += 2) {
        memset(dec + d, enc[k + 1], enc[k]);
        d += enc[k];
    }
    for (int64_t k = 0; k < m; k++) sum += enc[k];
    printf("%lld %lld %d\n", (long long)m, (long long)sum, d == n && memcmp(dec, data, n) == 0);
    free(data);
    free(enc);
    free(dec);
    return 0;
}
